window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e62645f1c7dcae7b"]={"versions": [{"id": "FIG-e62645f1c7dcae7b", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die strukturelle Zuordnung von Service-Instanzen (<code>ServiceInstanceToMachineMapping</code>) zu physischen oder virtuellen Ausführungsumgebungen (<code>Machine</code>) und deren Netzwerkanbindungen über Kommunikationskonnektoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>ARElement</code>): Zentrales Mapping-Element zur Zuordnung von Service-Instanzen zu Maschinen und Konnektoren.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>ARElement</code>): Repräsentiert die Instanz eines Adaptive-Dienstes. Assoziiert von <code>ServiceInstanceToMachineMapping</code> über die gerichtete Referenz <code>+serviceInstance</code> (Multiplizität <code>0..1</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>ARElement</code>): Spezifiziert das Deployment der Schnittstelle. Assoziiert von <code>AdaptivePlatformServiceInstance</code> über die gerichtete Referenz <code>+serviceInterface</code> (Multiplizität <code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Abstrakter Endpunkt für Netzwerkkommunikation. Assoziiert von <code>ServiceInstanceToMachineMapping</code> über die gerichtete Referenz <code>+communicationConnector</code> (Multiplizität <code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Modelliert die Host-Maschine. Besitzt über eine Komposition (<code>+communicationConnector</code>, Multiplizität <code>0..*</code>) null bis viele <code>CommunicationConnector</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen definieren verbindliche Vorgaben für die Manifest-Modellierung in AUTOSAR Adaptive. Ein <code>ServiceInstanceToMachineMapping</code> referenziert maximal eine <code>AdaptivePlatformServiceInstance</code> (<code>0..1</code>) und maximal einen <code>CommunicationConnector</code> (<code>0..1</code>). Jede <code>Machine</code> kapselt per Komposition ihre <code>CommunicationConnector</code> (<code>0..*</code>). Generatoren für Kommunikations-Stacks und Manifest-Parser werten diese Referenzen zur Konfiguration des Service-Routings und der Netzwerkschnittstellen aus.</p>"}, {"id": "FIG-4663cbc3f113b188", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die strukturelle Zuordnung von Service-Instanzen (<code>ServiceInstanceToMachineMapping</code>) zu physischen oder virtuellen Ausführungsumgebungen (<code>Machine</code>) und deren Netzwerkanbindungen über Kommunikationskonnektoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Zentrales Mapping-Element zur Zuordnung von Service-Instanzen zu Maschinen und Konnektoren.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Repräsentiert die Instanz eines Adaptive-Dienstes. Assoziiert von <code>ServiceInstanceToMachineMapping</code> über die gerichtete Referenz <code>+serviceInstance</code> (Multiplizität <code>0..1</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Spezifiziert das Deployment der Schnittstelle. Assoziiert von <code>AdaptivePlatformServiceInstance</code> über die gerichtete Referenz <code>+serviceInterface</code> (Multiplizität <code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Abstrakter Endpunkt für Netzwerkkommunikation. Assoziiert von <code>ServiceInstanceToMachineMapping</code> über die gerichtete Referenz <code>+communicationConnector</code> (Multiplizität <code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Modelliert die Host-Maschine. Enthält über eine Komposition (<code>+communicationConnector</code>, Multiplizität <code>0..*</code>) null bis viele <code>CommunicationConnector</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen definieren verbindliche Vorgaben für die Manifest-Modellierung in AUTOSAR Adaptive. <code>ServiceInstanceToMachineMapping</code>, <code>AdaptivePlatformServiceInstance</code> und <code>ServiceInterfaceDeployment</code> sind als <code>UploadablePackageElement</code> paketierbar und aktualisierbar. Ein <code>ServiceInstanceToMachineMapping</code> referenziert maximal eine <code>AdaptivePlatformServiceInstance</code> (<code>0..1</code>) und maximal einen <code>CommunicationConnector</code> (<code>0..1</code>). Die <code>Machine</code> aggregiert kompositionell null bis viele Konnektoren.</p>"}, {"id": "FIG-190fd156ec5becfd", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Verknüpft eine Service-Instanz mit einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Instanz eines Adaptive-Dienstes. Referenziert über <code>+serviceInstance</code> (<code>0..1</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Schnittstellen-Deployment, referenziert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterface</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt, referenziert von <code>ServiceInstanceToMachineMapping</code> über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Repräsentiert die Maschine und referenziert über die gerichtete Assoziation <code>+machineDesign</code> genau ein <code>MachineDesign</code> (Multiplizität <code>1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>): Beschreibt den Hardware-/Netzwerkentwurf der Maschine. Enthält das Attribut <code>+ pnResetTimer : TimeValue [0..1]</code> und aggregiert per Komposition null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Zuordnung von Konnektoren zur Maschine erfolgt über die Entwurfsklasse <code>MachineDesign</code>. <code>Machine</code> referenziert obligatorisch genau ein <code>MachineDesign</code> (<code>1</code>). Über <code>pnResetTimer</code> kann ein optionaler Timeout für das Zurücksetzen von Partial-Networking-Clustern konfiguriert werden. Die Bindung von Service-Instanzen an Konnektoren erfolgt über <code>ServiceInstanceToMachineMapping</code> mit jeweils <code>0..1</code>-Kardinalität.</p>"}, {"id": "FIG-ce16706b28035e8c", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Verknüpft mehrere Service-Instanzen mit einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Instanz eines Adaptive-Dienstes. Assoziiert von <code>ServiceInstanceToMachineMapping</code> über die gerichtete Referenz <code>+serviceInstance</code> (Multiplizität <code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Schnittstellen-Deployment, referenziert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterface</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt, referenziert von <code>ServiceInstanceToMachineMapping</code> über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Host-Maschine, referenziert über <code>+machineDesign</code> genau ein <code>MachineDesign</code> (Multiplizität <code>1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>): Modelliert den Netzwerkentwurf mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Hält per Komposition null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Multiplizität der Rolle <code>+serviceInstance</code> an <code>ServiceInstanceToMachineMapping</code> erlaubt die Zuordnung mehrerer Service-Instanzen (<code>0..*</code>) zu einem Mapping bzw. Konnektor. Über das Attribut <code>accessControl</code> an <code>MachineDesign</code> lässt sich optional das Zugriffssteuerungsverfahren festlegen. Die Konnektoren werden über die kompositionelle Beziehung von <code>MachineDesign</code> verwaltet.</p>"}, {"id": "FIG-a648431613b0f4d0", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Verknüpft mehrere Service-Instanzen mit einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Instanz eines Adaptive-Dienstes. Assoziiert von <code>ServiceInstanceToMachineMapping</code> über die gerichtete Referenz <code>+serviceInstance</code> (Multiplizität <code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Schnittstellen-Deployment, referenziert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterface</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt, referenziert von <code>ServiceInstanceToMachineMapping</code> über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Host-Maschine, referenziert über <code>+machineDesign</code> genau ein <code>MachineDesign</code> (Multiplizität <code>1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>): Modelliert den Netzwerkentwurf mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Hält per Komposition null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Multiplizität der Rolle <code>+serviceInstance</code> an <code>ServiceInstanceToMachineMapping</code> erlaubt die Zuordnung mehrerer Service-Instanzen (<code>0..*</code>) zu einem Mapping bzw. Konnektor. Über das Attribut <code>accessControl</code> an <code>MachineDesign</code> lässt sich optional das Zugriffssteuerungsverfahren festlegen. Die Konnektoren werden über die kompositionelle Beziehung von <code>MachineDesign</code> verwaltet.</p>"}, {"id": "FIG-de5245fee23313d3", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Zuordnung von Service-Instanzen zu einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Service-Instanz, assoziiert über <code>+serviceInstance</code> (<code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Deployment der Service-Schnittstelle, assoziiert von <code>AdaptivePlatformServiceInstance</code> über die gerichtete Referenz <code>+serviceInterfaceDeployment</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt mit dem Attribut <code>+ createEcuWakeupSource: Boolean [0..1]</code>. Assoziiert von <code>ServiceInstanceToMachineMapping</code> über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Besitzt das Attribut <code>+ trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum</code>. Referenziert über die gerichtete Assoziation <code>+machineDesign</code> genau ein <code>MachineDesign</code> (Multiplizität <code>1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>): Entwurfselement mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Komponiert null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Manifest definiert Steuerattribute für das Startverhalten vertrauenswürdiger Executables auf der Maschine (<code>trustedPlatformExecutableLaunchBehavior</code>) sowie die optionale Generierung von ECU-Aufweckquellen am Konnektor (<code>createEcuWakeupSource</code>). Die Referenz von <code>AdaptivePlatformServiceInstance</code> zum Schnittstellendeployment wird über die Rolle <code>+serviceInterfaceDeployment</code> (<code>0..1</code>) modelliert. Ein Mapping kann mehrere Service-Instanzen (<code>0..*</code>) bündeln.</p>"}, {"id": "FIG-f8a3870a6f776b1b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Zuordnung von Service-Instanzen zu einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Service-Instanz, assoziiert über <code>+serviceInstance</code> (<code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Deployment der Service-Schnittstelle, assoziiert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterfaceDeployment</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt mit dem Attribut <code>+ createEcuWakeupSource: Boolean [0..1]</code>. Assoziiert über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Besitzt das Attribut <code>+ trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum</code>. Referenziert über <code>+machineDesign</code> genau ein <code>MachineDesign</code> (Multiplizität <code>1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>): Entwurfselement mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code>, <code>+ pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Komponiert null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Über <code>pncPrepareSleepTimer</code> am <code>MachineDesign</code> wird ein optionaler Timer für die Vorbereitung des Schlafmodus partieller Netzwerke (PNC) parametriert, ergänzend zum <code>pnResetTimer</code>. Die übrigen semantischen Vorgaben für Mappings, Wakeup-Quellen und Ausführungsmodi vertrauenswürdiger Plattform-Executables bleiben unverändert verbindlich.</p>"}, {"id": "FIG-f5a3b25ade58cb12", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Zuordnung von Service-Instanzen zu einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Service-Instanz, assoziiert über <code>+serviceInstance</code> (<code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Deployment der Service-Schnittstelle, assoziiert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterfaceDeployment</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt mit den Attributen <code>+ createEcuWakeupSource: Boolean [0..1]</code> und <code>+ pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>. Assoziiert über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Besitzt das Attribut <code>+ trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum</code>. Referenziert über <code>+machineDesign</code> genau ein <code>MachineDesign</code> (Multiplizität <code>1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>): Entwurfselement mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code>, <code>+ pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Komponiert null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>, gekennzeichnet mit <code>«atpSplitable»</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Über <code>pncPrepareSleepTimer</code> am <code>MachineDesign</code> wird ein optionaler Timer für die Vorbereitung des Schlafmodus partieller Netzwerke (PNC) parametriert, ergänzend zum <code>pnResetTimer</code>. Das Attribut <code>pncFilterArrayMask</code> an <code>CommunicationConnector</code> ermöglicht das geordnete Konfigurieren von Masken für Teilnetzwerk-Filter. Die Kennzeichnung der Konnektor-Komposition als <code>«atpSplitable»</code> gestattet die Verteilung der Konnektordefinitionen über mehrere Manifest-Dateien. Die übrigen semantischen Vorgaben für Mappings, Wakeup-Quellen und Ausführungsmodi vertrauenswürdiger Plattform-Executables sind verbindlich.</p>"}, {"id": "FIG-8673a9fb1e3548b2", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadablePackageElement</code>): Zuordnung von Service-Instanzen zu einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadablePackageElement</code>): Service-Instanz, assoziiert über <code>+serviceInstance</code> (<code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadablePackageElement</code>): Deployment der Service-Schnittstelle, assoziiert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterfaceDeployment</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt mit den Attributen <code>+ createEcuWakeupSource: Boolean [0..1]</code> und <code>+ pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>. Assoziiert über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>ARElement</code>, <code>AtpStructureElement</code>): Besitzt das Attribut <code>+ trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code>. Referenziert über <code>+machineDesign</code> optional ein <code>MachineDesign</code> (Multiplizität <code>0..1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>): Entwurfselement mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code>, <code>+ pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Komponiert null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>, gekennzeichnet mit <code>«atpSplitable»</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Über <code>pncPrepareSleepTimer</code> am <code>MachineDesign</code> wird ein optionaler Timer für die Vorbereitung des Schlafmodus partieller Netzwerke (PNC) parametriert, ergänzend zum <code>pnResetTimer</code>. Das Attribut <code>pncFilterArrayMask</code> an <code>CommunicationConnector</code> ermöglicht das geordnete Konfigurieren von Masken für Teilnetzwerk-Filter. Durch die optionale Kardinalität (<code>0..1</code>) bei <code>trustedPlatformExecutableLaunchBehavior</code> und <code>+machineDesign</code> an der <code>Machine</code> wird die Modellierung flexibler gestaltet, sodass Maschinen ohne zugewiesenes Maschinendesign oder ohne explizite Vorgabe des Launch-Verhaltens vertrauenswürdiger Plattform-Executables zulässig sind.</p>"}, {"id": "FIG-3c33a196c3b44214", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadableDesignElement</code>): Zuordnung von Service-Instanzen zu einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadableDesignElement</code>): Service-Instanz, assoziiert über <code>+serviceInstance</code> (<code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadableDesignElement</code>): Deployment der Service-Schnittstelle, assoziiert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterfaceDeployment</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt mit den Attributen <code>+ createEcuWakeupSource: Boolean [0..1]</code> und <code>+ pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>. Assoziiert über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>AtpStructureElement</code>, <code>UploadableDeploymentElement</code>): Besitzt das Attribut <code>+ trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code>. Referenziert über <code>+machineDesign</code> optional ein <code>MachineDesign</code> (Multiplizität <code>0..1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>): Entwurfselement mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code>, <code>+ pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Komponiert null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>, gekennzeichnet mit <code>«atpSplitable»</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Über <code>pncPrepareSleepTimer</code> am <code>MachineDesign</code> wird ein optionaler Timer für die Vorbereitung des Schlafmodus partieller Netzwerke (PNC) parametriert, ergänzend zum <code>pnResetTimer</code>. Das Attribut <code>pncFilterArrayMask</code> an <code>CommunicationConnector</code> ermöglicht das geordnete Konfigurieren von Masken für Teilnetzwerk-Filter. Die Neuklassifizierung der Entitäten trennt Entwurfs- (<code>UploadableDesignElement</code> für <code>ServiceInstanceToMachineMapping</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code>, <code>MachineDesign</code>) und Deployment-Ebene (<code>UploadableDeploymentElement</code> für <code>Machine</code>), was bei der Strukturierung und Paketierung von Update- und Deployment-Artefakten zu beachten ist.</p>"}, {"id": "FIG-791986a25cfac23e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadableDesignElement</code>): Zuordnung von Service-Instanzen zu einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadableDesignElement</code>): Service-Instanz, assoziiert über <code>+serviceInstance</code> (<code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadableDesignElement</code>): Deployment der Service-Schnittstelle, assoziiert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterfaceDeployment</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt mit den Attributen <code>+ createEcuWakeupSource: Boolean [0..1]</code> und <code>+ pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>. Assoziiert über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>AtpStructureElement</code>, <code>UploadableDeploymentElement</code>): Besitzt das Attribut <code>+ trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code>. Referenziert über <code>+machineDesign</code> optional ein <code>MachineDesign</code> (Multiplizität <code>0..1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>): Entwurfselement mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code>, <code>+ pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Komponiert null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>, gekennzeichnet mit <code>«atpSplitable»</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Über <code>pncPrepareSleepTimer</code> am <code>MachineDesign</code> wird ein optionaler Timer für die Vorbereitung des Schlafmodus partieller Netzwerke (PNC) parametriert, ergänzend zum <code>pnResetTimer</code>. Das Attribut <code>pncFilterArrayMask</code> an <code>CommunicationConnector</code> ermöglicht das geordnete Konfigurieren von Masken für Teilnetzwerk-Filter. Die Neuklassifizierung der Entitäten trennt Entwurfs- (<code>UploadableDesignElement</code> für <code>ServiceInstanceToMachineMapping</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code>, <code>MachineDesign</code>) und Deployment-Ebene (<code>UploadableDeploymentElement</code> für <code>Machine</code>), was bei der Strukturierung und Paketierung von Update- und Deployment-Artefakten zu beachten ist.</p>"}, {"id": "FIG-c5863f38c7071f28", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Manifests der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Zuordnung von Service-Instanzen zu Maschinen und deren Netzwerk-Konnektoren unter Einbindung des Maschinendesigns (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInstanceToMachineMapping</code> (Stereotyp: <code>UploadableDesignElement</code>): Zuordnung von Service-Instanzen zu einem Kommunikationskonnektor.\n</li><li><code>AdaptivePlatformServiceInstance</code> (Stereotyp: <code>UploadableDesignElement</code>): Service-Instanz, assoziiert über <code>+serviceInstance</code> (<code>0..*</code>).\n</li><li><code>ServiceInterfaceDeployment</code> (Stereotyp: <code>UploadableDesignElement</code>): Deployment der Service-Schnittstelle, assoziiert von <code>AdaptivePlatformServiceInstance</code> über <code>+serviceInterfaceDeployment</code> (<code>0..1</code>).\n</li><li><code>CommunicationConnector</code> (Stereotyp: <code>Identifiable</code>, abstrakt/kursiv): Kommunikations-Endpunkt mit den Attributen <code>+ createEcuWakeupSource: Boolean [0..1]</code> und <code>+ pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>. Assoziiert über <code>+communicationConnector</code> (<code>0..1</code>).\n</li><li><code>Machine</code> (Stereotypen: <code>AtpStructureElement</code>, <code>UploadableDeploymentElement</code>): Besitzt das Attribut <code>+ trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code>. Referenziert über <code>+machineDesign</code> optional ein <code>MachineDesign</code> (Multiplizität <code>0..1</code>).\n</li><li><code>MachineDesign</code> (Stereotypen: <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>): Entwurfselement mit den Attributen <code>+ accessControl: AccessControlEnum [0..1]</code>, <code>+ pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>+ pnResetTimer: TimeValue [0..1]</code>. Komponiert null bis viele <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>, gekennzeichnet mit <code>«atpSplitable»</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm definiert rein statische Metamodell-Strukturen für das Deployment-Manifest ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Verknüpfungen etablieren zur Konfigurations- bzw. Entwurfszeit die Beziehung zwischen einer Service-Instanz, ihrem Schnittstellendeployment und dem zuständigen Kommunikations-Konnektor einer Maschine.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Über <code>pncPrepareSleepTimer</code> am <code>MachineDesign</code> wird ein optionaler Timer für die Vorbereitung des Schlafmodus partieller Netzwerke (PNC) parametriert, ergänzend zum <code>pnResetTimer</code>. Das Attribut <code>pncFilterArrayMask</code> an <code>CommunicationConnector</code> ermöglicht das geordnete Konfigurieren von Masken für Teilnetzwerk-Filter. Die Neuklassifizierung der Entitäten trennt Entwurfs- (<code>UploadableDesignElement</code> für <code>ServiceInstanceToMachineMapping</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code>, <code>MachineDesign</code>) und Deployment-Ebene (<code>UploadableDeploymentElement</code> für <code>Machine</code>), was bei der Strukturierung und Paketierung von Update- und Deployment-Artefakten zu beachten ist.</p>"}], "trans": [{"from": "FIG-e62645f1c7dcae7b", "to": "FIG-4663cbc3f113b188", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Vererbungshierarchie von <code>ServiceInstanceToMachineMapping</code>, <code>AdaptivePlatformServiceInstance</code> und <code>ServiceInterfaceDeployment</code> ändert sich von <code>ARElement</code> zu <code>UploadablePackageElement</code>.\n</li><li>Die Komposition von <code>CommunicationConnector</code> wird von <code>Machine</code> auf eine übergeordnete Position umstrukturiert.\n</li><li>Die Referenz <code>communicationConnector</code> von <code>Machine</code> zu <code>CommunicationConnector</code> (<code>0..*</code>) wird vertikal ausgerichtet.\n</li><li>Das Gesamtlayout des UML-Klassendiagramms wurde neu arrangiert (vertikale Stapelung der Service-Elemente rechts neben dem Mapping).\n</li></ul>"}, {"from": "FIG-4663cbc3f113b188", "to": "FIG-190fd156ec5becfd", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Klasse <code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code>) wird eingeführt und besitzt das Attribut <code>pnResetTimer: TimeValue [0..1]</code>.\n</li><li>Die Assoziation <code>machineDesign</code> mit Multiplizität <code>1</code> wird von <code>Machine</code> zu <code>MachineDesign</code> ergänzt.\n</li><li>Die Komposition von <code>CommunicationConnector</code> (<code>+communicationConnector 0..*</code>) geht nicht mehr von <code>Machine</code>, sondern von <code>MachineDesign</code> aus.\n</li></ul>"}, {"from": "FIG-190fd156ec5becfd", "to": "FIG-ce16706b28035e8c", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Klasse <code>MachineDesign</code> wird das Attribut <code>accessControl: AccessControlEnum [0..1]</code> ergänzt.\n</li><li>Die Multiplizität der Assoziationsrolle <code>+serviceInstance</code> von <code>ServiceInstanceToMachineMapping</code> zu <code>AdaptivePlatformServiceInstance</code> ändert sich von <code>0..1</code> auf <code>0..*</code>.\n</li></ul>"}, {"from": "FIG-ce16706b28035e8c", "to": "FIG-a648431613b0f4d0", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a648431613b0f4d0", "to": "FIG-de5245fee23313d3", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Klasse <code>Machine</code> wird das Attribut <code>trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum</code> ergänzt.\n</li><li>In der Klasse <code>CommunicationConnector</code> wird das Attribut <code>createEcuWakeupSource: Boolean [0..1]</code> ergänzt.\n</li><li>Die Assoziationsrolle von <code>AdaptivePlatformServiceInstance</code> zu <code>ServiceInterfaceDeployment</code> wird von <code>+serviceInterface</code> in <code>+serviceInterfaceDeployment</code> umbenannt.\n</li><li>Die Anordnung von <code>Machine</code> und <code>MachineDesign</code> wird von horizontal nebeneinander auf vertikal untereinander umgestellt.\n</li></ul>"}, {"from": "FIG-de5245fee23313d3", "to": "FIG-f8a3870a6f776b1b", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Klasse <code>MachineDesign</code> wird das Attribut <code>pncPrepareSleepTimer: TimeValue [0..1]</code> ergänzt.\n</li></ul>"}, {"from": "FIG-f8a3870a6f776b1b", "to": "FIG-f5a3b25ade58cb12", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CommunicationConnector</code>: Attribut <code>+ pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code> hinzugefügt.\n</li><li>Komposition zwischen <code>MachineDesign</code> und <code>CommunicationConnector</code>: Stereotyp <code>«atpSplitable»</code> an der Assoziationsrolle <code>+communicationConnector</code> ergänzt.\n</li></ul>"}, {"from": "FIG-f5a3b25ade58cb12", "to": "FIG-8673a9fb1e3548b2", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Machine</code>: Multiplizität des Attributs <code>trustedPlatformExecutableLaunchBehavior</code> von obligatorisch (<code>1</code>) auf optional (<code>[0..1]</code>) geändert.\n</li><li>Assoziation <code>+machineDesign</code> von <code>Machine</code> zu <code>MachineDesign</code>: Multiplizität an der Zielrolle von <code>1</code> auf <code>0..1</code> gelockert.\n</li></ul>"}, {"from": "FIG-8673a9fb1e3548b2", "to": "FIG-3c33a196c3b44214", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Machine</code>: Stereotyp <code>ARElement</code> durch <code>UploadableDeploymentElement</code> ersetzt.\n</li><li><code>MachineDesign</code>: Stereotyp <code>UploadableDesignElement</code> ergänzt (neben <code>AtpStructureElement</code> und <code>FibexElement</code>).\n</li><li><code>ServiceInstanceToMachineMapping</code>: Stereotyp <code>UploadablePackageElement</code> durch <code>UploadableDesignElement</code> ersetzt.\n</li><li><code>AdaptivePlatformServiceInstance</code>: Stereotyp <code>UploadablePackageElement</code> durch <code>UploadableDesignElement</code> ersetzt.\n</li><li><code>ServiceInterfaceDeployment</code>: Stereotyp <code>UploadablePackageElement</code> durch <code>UploadableDesignElement</code> ersetzt.\n</li></ul>"}, {"from": "FIG-3c33a196c3b44214", "to": "FIG-791986a25cfac23e", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-791986a25cfac23e", "to": "FIG-c5863f38c7071f28", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
